1	/**
2	 * Quiz Engine — generates question sets, workbooks, and answer keys.
3	 */
4	
5	import { TopicDefinition, resolveTopic } from "./topics.js";
6	import { Prng } from "./random.js";
7	
8	export type QuestionType = "multiple_choice" | "short_answer" | "true_false" | "fill_in" | "transfer";
9	
10	export interface QuizQuestion {
11	  id: string;
12	  type: QuestionType;
13	  level: "recall" | "comprehension" | "application" | "analysis" | "transfer";
14	  question: string;
15	  options?: string[]; // For multiple_choice, true_false
16	  correctAnswer: string;
17	  explanation: string;
18	  rubric?: string; // For short_answer / transfer
19	}
20	
21	export interface QuizReview {
22	  status: "passed" | "revised";
23	  issues: string[];
24	  duplicatesRemoved: number;
25	  maxQuestionChars: number;
26	  maxAnswerChars: number;
27	  maxExplanationChars: number;
28	  maxRubricChars: number;
29	  maxOptionChars: number;
30	  limits: QuizLimits;
31	}
32	
33	export interface Quiz {
34	  topic: string;
35	  slug: string;
36	  generatedAt: string;
37	  questions: QuizQuestion[];
38	  answerKey: Map<string, string>;
39	  totalPoints: number;
40	  review: QuizReview;
41	}
42	
43	export interface WorkbookSection {
44	  title: string;
45	  instructions: string;
46	  questions: QuizQuestion[];
47	}
48	
49	export interface Workbook {
50	  topic: string;
51	  slug: string;
52	  sections: WorkbookSection[];
53	  generatedAt: string;
54	}
55	
56	export interface QuizLimits {
57	  questionChars: number;
58	  answerChars: number;
59	  explanationChars: number;
60	  rubricChars: number;
61	  optionChars: number;
62	}
63	
64	export type QuizLimitOverrides = Partial<QuizLimits>;
65	
66	/**
67	 * A question crafted by the teaching agent, grounded in the actual material.
68	 * Only `question`, `correctAnswer`, and `explanation` are required; the rest is
69	 * inferred. When authored questions are supplied they replace the templated set.
70	 */
71	export interface AuthoredQuestion {
72	  type?: QuestionType;
73	  level?: QuizQuestion["level"];
74	  question: string;
75	  options?: string[];
76	  correctAnswer: string;
77	  explanation: string;
78	  rubric?: string;
79	}
80	
81	export interface GenerateQuizOptions {
82	  limits?: QuizLimitOverrides;
83	  /** Agent-crafted questions grounded in real material. Used instead of templates when 2+ are valid. */
84	  authored?: AuthoredQuestion[];
85	}
86	
87	const QUIZ_LEVELS: ReadonlySet<QuizQuestion["level"]> = new Set([
88	  "recall",
89	  "comprehension",
90	  "application",
91	  "analysis",
92	  "transfer",
93	]);
94	
95	const QUIZ_LEVEL_CYCLE: QuizQuestion["level"][] = [
96	  "recall",
97	  "comprehension",
98	  "application",
99	  "analysis",
100	  "transfer",
101	];
102	
103	/**
104	 * Convert agent-authored question specs into validated QuizQuestions. Drops
105	 * entries missing a question/answer/explanation, infers type and level, ensures
106	 * multiple-choice options contain the correct answer, and supplies a default
107	 * rubric for open-ended questions.
108	 */
109	export function buildAuthoredQuestions(topic: TopicDefinition, authored: AuthoredQuestion[]): QuizQuestion[] {
110	  const out: QuizQuestion[] = [];
111	  authored.forEach((raw, i) => {
112	    const question = (raw.question ?? "").trim();
113	    const correctAnswer = (raw.correctAnswer ?? "").trim();
114	    const explanation = (raw.explanation ?? "").trim();
115	    if (!question || !correctAnswer || !explanation) return;
116	
117	    let options = Array.isArray(raw.options)
118	      ? raw.options.map((o) => String(o).trim()).filter(Boolean)
119	      : undefined;
120	
121	    const level: QuizQuestion["level"] = raw.level && QUIZ_LEVELS.has(raw.level)
122	      ? raw.level
123	      : QUIZ_LEVEL_CYCLE[i % QUIZ_LEVEL_CYCLE.length];
124	
125	    let type: QuestionType = raw.type ?? (options && options.length >= 2 ? "multiple_choice" : "short_answer");
126	
127	    if (type === "multiple_choice" && options) {
128	      if (!options.some((o) => o === correctAnswer)) options = [correctAnswer, ...options];
129	      if (options.length < 2) type = "short_answer";
130	    }
131	    if (type === "multiple_choice" && (!options || options.length < 2)) {
132	      type = "short_answer";
133	    }
134	
135	    const isOpen = type === "short_answer" || type === "transfer" || type === "fill_in";
136	    const rubric = raw.rubric?.trim()
137	      ? raw.rubric.trim()
138	      : isOpen
139	        ? "1pt vague, 2pts captures the essence, 3pts precise with a concrete detail or limit."
140	        : undefined;
141	
142	    out.push({
143	      id: `${topic.slug}-q${out.length + 1}`,
144	      type,
145	      level,
146	      question,
147	      options: options && options.length ? options : undefined,
148	      correctAnswer,
149	      explanation,
150	      rubric,
151	    });
152	  });
153	  return out;
154	}
155	
156	// ─── Question Generation ──────────────────────────────────────────────────
157	
158	const DEFAULT_QUIZ_LIMITS: QuizLimits = {
159	  questionChars: 180,
160	  answerChars: 220,
161	  explanationChars: 220,
162	  rubricChars: 120,
163	  optionChars: 140,
164	};
165	
166	function clampLimit(value: number | undefined, min: number, max: number, fallback: number): number {
167	  if (value === undefined || !Number.isFinite(value)) return fallback;
168	  return Math.max(min, Math.min(max, Math.round(value)));
169	}
170	
171	export function resolveQuizLimits(overrides: QuizLimitOverrides = {}): QuizLimits {
172	  return {
173	    questionChars: clampLimit(overrides.questionChars, 80, 320, 180),
174	    answerChars: clampLimit(overrides.answerChars, 80, 500, 220),
175	    explanationChars: clampLimit(overrides.explanationChars, 80, 500, 220),
176	    rubricChars: clampLimit(overrides.rubricChars, 60, 220, 120),
177	    optionChars: clampLimit(overrides.optionChars, 40, 220, 140),
178	  };
179	}
180	
181	function limitText(value: string, maxChars: number): string {
182	  const text = value.replace(/\s+/g, " ").trim();
183	  if (text.length <= maxChars) return text;
184	  const clipped = text.slice(0, Math.max(0, maxChars - 1)).trimEnd();
185	  const boundary = Math.max(clipped.lastIndexOf("."), clipped.lastIndexOf(";"), clipped.lastIndexOf(","));
186	  const shortened = boundary >= maxChars * 0.6 ? clipped.slice(0, boundary) : clipped;
187	  return `${shortened.trimEnd()}…`;
188	}
189	
190	function pickDistinct(items: string[], prng: Prng, idx: number, fallback: string): string {
191	  const clean = items.map((item) => item.trim()).filter(Boolean);
192	  if (clean.length === 0) return fallback;
193	  const start = prng.int(0, clean.length - 1);
194	  return clean[(start + idx - 1) % clean.length] ?? fallback;
195	}
196	
197	function normalizeQuestion(value: string): string {
198	  return value
199	    .toLowerCase()
200	    .replace(/["'`]/g, "")
201	    .replace(/[^a-z0-9\s]/g, " ")
202	    .split(/\s+/)
203	    .filter((word) => word.length > 2 && !["the", "and", "for", "with", "your", "this", "that", "about"].includes(word))
204	    .join(" ");
205	}
206	
207	function tokenSimilarity(a: string, b: string): number {
208	  const left = new Set(normalizeQuestion(a).split(/\s+/).filter(Boolean));
209	  const right = new Set(normalizeQuestion(b).split(/\s+/).filter(Boolean));
210	  if (left.size === 0 || right.size === 0) return 0;
211	  let intersection = 0;
212	  for (const token of left) {
213	    if (right.has(token)) intersection++;
214	  }
215	  return intersection / (left.size + right.size - intersection);
216	}
217	
218	function enforceQuestionLimits(q: QuizQuestion, limits: QuizLimits): QuizQuestion {
219	  return {
220	    ...q,
221	    question: limitText(q.question, limits.questionChars),
222	    correctAnswer: limitText(q.correctAnswer, limits.answerChars),
223	    explanation: limitText(q.explanation, limits.explanationChars),
224	    rubric: q.rubric ? limitText(q.rubric, limits.rubricChars) : undefined,
225	    options: q.options?.map((option) => limitText(option, limits.optionChars)),
226	  };
227	}
228	
229	function reviewQuizQuestions(questions: QuizQuestion[], limits: QuizLimits): QuizReview {
230	  const issues: string[] = [];
231	  let duplicatesRemoved = 0;
232	  const seen: QuizQuestion[] = [];
233	
234	  for (const q of questions) {
235	    if (q.question.length > limits.questionChars) issues.push(`${q.id}: question exceeded ${limits.questionChars} chars`);
236	    if (q.correctAnswer.length > limits.answerChars) issues.push(`${q.id}: answer exceeded ${limits.answerChars} chars`);
237	    if (q.explanation.length > limits.explanationChars) issues.push(`${q.id}: explanation exceeded ${limits.explanationChars} chars`);
238	    if (q.rubric && q.rubric.length > limits.rubricChars) issues.push(`${q.id}: rubric exceeded ${limits.rubricChars} chars`);
239	    for (const option of q.options ?? []) {
240	      if (option.length > limits.optionChars) issues.push(`${q.id}: option exceeded ${limits.optionChars} chars`);
241	    }
242	    if (seen.some((prior) => tokenSimilarity(prior.question, q.question) >= 0.82)) {
243	      duplicatesRemoved++;
244	      issues.push(`${q.id}: similar to an earlier question`);
245	    } else {
246	      seen.push(q);
247	    }
248	  }
249	
250	  return {
251	    status: issues.length === 0 ? "passed" : "revised",
252	    issues,
253	    duplicatesRemoved,
254	    maxQuestionChars: limits.questionChars,
255	    maxAnswerChars: limits.answerChars,
256	    maxExplanationChars: limits.explanationChars,
257	    maxRubricChars: limits.rubricChars,
258	    maxOptionChars: limits.optionChars,
259	    limits,
260	  };
261	}
262	
263	function refineQuizQuestions(questions: QuizQuestion[], limits: QuizLimits): { questions: QuizQuestion[]; review: QuizReview } {
264	  const refined = questions.map((question) => enforceQuestionLimits(question, limits));
265	  const review = reviewQuizQuestions(refined, limits);
266	  return { questions: refined, review };
267	}
268	
269	function makeRecallQ(topic: TopicDefinition, _prng: Prng, idx: number): QuizQuestion {
270	  return {
271	    id: `${topic.slug}-r${idx}`,
272	    type: "short_answer",
273	    level: "recall",
274	    question: idx === 1
275	      ? `Define "${topic.title}" in your own words.`
276	      : `State the central idea of ${topic.title} without using the exact lesson wording.`,
277	    correctAnswer: topic.summary,
278	    explanation: `The core definition: ${topic.summary}`,
279	    rubric: `1pt vague, 2pts essence, 3pts precise with nuance.`,
280	  };
281	}
282	
283	function makeComprehensionQ(topic: TopicDefinition, prng: Prng, idx: number): QuizQuestion {
284	  const hook = pickDistinct(topic.intuition, prng, idx, "the concept");
285	  return {
286	    id: `${topic.slug}-c${idx}`,
287	    type: "short_answer",
288	    level: "comprehension",
289	    question: `Explain the intuition: "${hook}". Why is this a helpful way to think about ${topic.title}?`,
290	    correctAnswer: `Because it maps ${topic.title} to something concrete before formal notation.`,
291	    explanation: `Intuition first, formalism second: ${hook}`,
292	    rubric: `2pts: explains the metaphor. 3pts: identifies when it breaks down.`,
293	  };
294	}
295	
296	function makeApplicationQ(topic: TopicDefinition, prng: Prng, idx: number): QuizQuestion {
297	  const ex = pickDistinct(topic.examples, prng, idx, `an example involving ${topic.title}`);
298	  return {
299	    id: `${topic.slug}-a${idx}`,
300	    type: "short_answer",
301	    level: "application",
302	    question: idx === 1
303	      ? `Work through this example: ${ex}. Show the key reasoning steps.`
304	      : `Use ${topic.title} to solve or analyze this case: ${ex}. Name the rule you used.`,
305	    correctAnswer: `Follow the mechanics demonstrated in ${topic.title}.`,
306	    explanation: `Application grounds abstract knowledge: ${ex}`,
307	    rubric: `2pts attempt, 3pts correct mechanics, 4pts clear reasoning.`,
308	  };
309	}
310	
311	function makeMisconceptionQ(topic: TopicDefinition, prng: Prng, idx: number): QuizQuestion {
312	  const mis = topic.misconceptions;
313	  const m = mis[prng.int(0, mis.length - 1)] ?? "a common misconception";
314	  return {
315	    id: `${topic.slug}-m${idx}`,
316	    type: "multiple_choice",
317	    level: "comprehension",
318	    question: `Which of the following statements about ${topic.title} is FALSE?`,
319	    options: [
320	      `${m}`,
321	      `${topic.title} can be reasoned about using concrete examples.`,
322	      `A good answer should mention limits or boundary conditions.`,
323	      `The formal version should connect back to the intuition.`,
324	    ],
325	    correctAnswer: `${m}`,
326	    explanation: `"${m}" is a known misconception. The other statements are generally true.`,
327	  };
328	}
329	
330	function makeTransferQ(topic: TopicDefinition, prng: Prng, idx: number): QuizQuestion {
331	  const domain = pickDistinct(topic.interdisciplinaryHooks, prng, idx, "a new domain");
332	  return {
333	    id: `${topic.slug}-t${idx}`,
334	    type: "short_answer",
335	    level: "transfer",
336	    question: idx === 1
337	      ? `Apply ${topic.title} to ${domain}. What structure carries over?`
338	      : `Where would an analogy between ${topic.title} and ${domain} break down?`,
339	    correctAnswer: `A valid analogy that preserves structural relationships and acknowledges boundary conditions.`,
340	    explanation: `Transfer requires mapping invariants, not surface features, to ${domain}.`,
341	    rubric: `2pts surface analogy, 3pts structure, 4pts limits included.`,
342	  };
343	}
344	
345	export function generateQuiz(topicName: string, seed = 42, options: GenerateQuizOptions = {}): Quiz {
346	  const topic = resolveTopic(topicName);
347	  const prng = new Prng(seed);
348	  const limits = resolveQuizLimits(options.limits);
349	  const questions: QuizQuestion[] = [];
350	
351	  // Preferred path: the teaching agent crafted questions grounded in the real
352	  // material. Use them instead of the generic templates (which produce vacuous
353	  // "Define X in your own words" questions for any topic not hardcoded).
354	  const authored = options.authored ? buildAuthoredQuestions(topic, options.authored) : [];
355	  if (authored.length >= 2) {
356	    const refinedAuthored = refineQuizQuestions(authored, limits);
357	    const authoredKey = new Map<string, string>();
358	    for (const q of refinedAuthored.questions) authoredKey.set(q.id, q.correctAnswer);
359	    return {
360	      topic: topic.title,
361	      slug: topic.slug,
362	      generatedAt: new Date().toISOString(),
363	      questions: refinedAuthored.questions,
364	      answerKey: authoredKey,
365	      totalPoints: refinedAuthored.questions.reduce((s, q) => s + (q.rubric ? 3 : 1), 0),
366	      review: refinedAuthored.review,
367	    };
368	  }
369	
370	  // 2 recall
371	  questions.push(makeRecallQ(topic, prng, 1));
372	  questions.push(makeRecallQ(topic, prng, 2));
373	  // 2 comprehension
374	  questions.push(makeComprehensionQ(topic, prng, 1));
375	  questions.push(makeMisconceptionQ(topic, prng, 1));
376	  // 2 application
377	  questions.push(makeApplicationQ(topic, prng, 1));
378	  questions.push(makeApplicationQ(topic, prng, 2));
379	  // 2 transfer
380	  questions.push(makeTransferQ(topic, prng, 1));
381	  questions.push(makeTransferQ(topic, prng, 2));
382	
383	  const refined = refineQuizQuestions(questions, limits);
384	  const answerKey = new Map<string, string>();
385	  for (const q of refined.questions) {
386	    answerKey.set(q.id, q.correctAnswer);
387	  }
388	
389	  return {
390	    topic: topic.title,
391	    slug: topic.slug,
392	    generatedAt: new Date().toISOString(),
393	    questions: refined.questions,
394	    answerKey,
395	    totalPoints: refined.questions.reduce((s, q) => s + (q.rubric ? 3 : 1), 0),
396	    review: refined.review,
397	  };
398	}
399	
400	// ─── Workbook ─────────────────────────────────────────────────────────────
401	
402	export function generateWorkbook(topicName: string, seed = 42): Workbook {
403	  const topic = resolveTopic(topicName);
404	  const prng = new Prng(seed);
405	  const quiz = generateQuiz(topicName, seed);
406	
407	  const sections: WorkbookSection[] = [
408	    {
409	      title: "Part A: Foundation",
410	      instructions: "Answer every question without looking at notes. Retrieval practice beats re-reading.",
411	      questions: quiz.questions.filter(q => q.level === "recall" || q.level === "comprehension"),
412	    },
413	    {
414	      title: "Part B: Application",
415	      instructions: "Work each example out on paper or in a text editor. Show all steps.",
416	      questions: quiz.questions.filter(q => q.level === "application"),
417	    },
418	    {
419	      title: "Part C: Transfer",
420	      instructions: "Bridge this concept into unfamiliar territory. If your analogy feels too easy, it is probably too shallow.",
421	      questions: quiz.questions.filter(q => q.level === "transfer"),
422	    },
423	  ];
424	
425	  return {
426	    topic: topic.title,
427	    slug: topic.slug,
428	    sections,
429	    generatedAt: new Date().toISOString(),
430	  };
431	}
432	
433	// ─── Markdown output ──────────────────────────────────────────────────────
434	
435	export function quizToMarkdown(quiz: Quiz): string {
436	  const lines = [
437	    `# Quiz: ${quiz.topic}`,
438	    `> Generated: ${quiz.generatedAt}`,
439	    `> Reviewed: ${quiz.review.status}; limits q/a/expl/rubric/option ${quiz.review.maxQuestionChars}/${quiz.review.maxAnswerChars}/${quiz.review.maxExplanationChars}/${quiz.review.maxRubricChars}/${quiz.review.maxOptionChars} chars`,
440	    ``,
441	  ];
442	  for (const q of quiz.questions) {
443	    lines.push(`## ${q.id} — ${q.level} (${q.type})`);
444	    lines.push(q.question);
445	    if (q.options) {
446	      lines.push("");
447	      for (let i = 0; i < q.options.length; i++) {
448	        lines.push(`${String.fromCharCode(65 + i)}. ${q.options[i]}`);
449	      }
450	    }
451	    lines.push("");
452	    if (q.rubric) lines.push(`*Rubric:* ${q.rubric}`);
453	    lines.push("");
454	  }
455	  return lines.join("\n") + "\n";
456	}
457	
458	export function quizAnswerKeyToMarkdown(quiz: Quiz): string {
459	  const lines = [
460	    `# Answer Key: ${quiz.topic}`,
461	    "",
462	  ];
463	  for (const q of quiz.questions) {
464	    lines.push(`## ${q.id}`);
465	    lines.push(`**Answer:** ${q.correctAnswer}`);
466	    lines.push(`**Explanation:** ${q.explanation}`);
467	    lines.push("");
468	  }
469	  return lines.join("\n") + "\n";
470	}
471	
472	export function workbookToMarkdown(wb: Workbook): string {
473	  const lines = [
474	    `# Workbook: ${wb.topic}`,
475	    `> Self-paced. Do Part A in one sitting, Part B after a break, Part C tomorrow.`,
476	    "",
477	  ];
478	  for (const section of wb.sections) {
479	    lines.push(`---`);
480	    lines.push(`# ${section.title}`);
481	    lines.push(section.instructions);
482	    lines.push("");
483	    for (const q of section.questions) {
484	      lines.push(`### ${q.id} — ${q.level}`);
485	      lines.push(q.question);
486	      if (q.options) {
487	        for (let i = 0; i < q.options.length; i++) {
488	          lines.push(`${String.fromCharCode(65 + i)}. ${q.options[i]}`);
489	        }
490	      }
491	      lines.push("");
492	      lines.push(`*Space for answer:*`);
493	      lines.push("\n\n\n\n"); // Blank space
494	    }
495	  }
496	  return lines.join("\n") + "\n";
497	}
