1	/**
2	 * Learner Goals — long-horizon curriculum building.
3	 *
4	 * A goal captures something the learner wants to *accomplish* (a task or
5	 * project), then scaffolds an ordered curriculum of steps that build toward it.
6	 * Goals are persisted and their progress is tracked across sessions, so the
7	 * agent can pick up where the learner left off and sequence work over days or
8	 * weeks rather than a single chat.
9	 */
10	
11	import { resolveTopic } from "./core";
12	
13	export type GoalStepKind = "concept" | "practice" | "project" | "milestone" | "reflection";
14	export type GoalStepStatus = "not_started" | "in_progress" | "done";
15	export type GoalStatus = "active" | "completed" | "paused";
16	
17	export interface GoalStep {
18		id: string;
19		order: number;
20		title: string;
21		description: string;
22		kind: GoalStepKind;
23		/** Optional topic this step centers on (drives plan/quiz tooling). */
24		topic?: string;
25		successCriteria: string[];
26		status: GoalStepStatus;
27		completedAt?: string;
28	}
29	
30	export interface LearnerGoal {
31		id: string;
32		title: string;
33		description: string;
34		motivation?: string;
35		targetDate?: string;
36		status: GoalStatus;
37		steps: GoalStep[];
38		createdAt: number;
39		updatedAt: number;
40		sessionId?: string;
41	}
42	
43	export interface GoalStepInput {
44		title: string;
45		description?: string;
46		kind?: GoalStepKind;
47		topic?: string;
48		successCriteria?: string[];
49	}
50	
51	export interface GoalInput {
52		title: string;
53		description?: string;
54		motivation?: string;
55		targetDate?: string;
56		/** Agent-designed curriculum steps. When omitted, a scaffold is generated. */
57		steps?: GoalStepInput[];
58		/** Anchor topic used to auto-scaffold a curriculum when steps are omitted. */
59		topic?: string;
60	}
61	
62	const STEP_KINDS: GoalStepKind[] = ["concept", "practice", "project", "milestone", "reflection"];
63	
64	function makeId(prefix: string): string {
65		return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
66	}
67	
68	function normalizeKind(value: unknown): GoalStepKind {
69		return typeof value === "string" && (STEP_KINDS as string[]).includes(value)
70			? (value as GoalStepKind)
71			: "concept";
72	}
73	
74	/**
75	 * Auto-generate a long-horizon curriculum from an anchor topic when the agent
76	 * does not supply explicit steps. Mirrors the research → practice → build →
77	 * teach arc used elsewhere in Keating, but framed around the learner's goal.
78	 */
79	function scaffoldSteps(goalTitle: string, anchorTopic: string): GoalStepInput[] {
80		const topic = resolveTopic(anchorTopic || goalTitle);
81		const bridge = topic.interdisciplinaryHooks[0];
82		return [
83			{
84				title: `Foundations of ${topic.title}`,
85				description: `Build the vocabulary and intuition behind ${topic.title}${
86					topic.prerequisites.length ? `, shoring up prerequisites (${topic.prerequisites.slice(0, 3).join(", ")})` : ""
87				}.`,
88				kind: "concept",
89				topic: topic.title,
90				successCriteria: [
91					`Explain ${topic.title} in your own words`,
92					...topic.misconceptions.slice(0, 1).map((m) => `Avoid the misconception: ${m}`),
93				],
94			},
95			{
96				title: `Work through ${topic.title} in practice`,
97				description: `Solve concrete examples and exercises so ${topic.title} becomes usable, not just familiar.`,
98				kind: "practice",
99				topic: topic.title,
100				successCriteria: [
101					"Complete several worked examples with reasoning shown",
102					"Score 70%+ on a timed quiz for this step",
103				],
104			},
105			{
106				title: `Build toward: ${goalTitle}`,
107				description: `Apply ${topic.title} directly to a deliverable that advances "${goalTitle}".`,
108				kind: "project",
109				topic: topic.title,
110				successCriteria: [
111					`Produce a concrete artifact that moves "${goalTitle}" forward`,
112					"Identify what worked and what to improve next",
113				],
114			},
115			{
116				title: "Teach-back & reflect",
117				description: `Explain what you built and how ${topic.title}${bridge ? ` connects to ${bridge}` : ""} to consolidate transfer.`,
118				kind: "reflection",
119				topic: topic.title,
120				successCriteria: [
121					"Teach the concept to someone (or rubber-duck it)",
122					"Name one open question to pursue next",
123				],
124			},
125		];
126	}
127	
