        for (const line of controlLines) lines.push(`    ${line}`);
      }
      if (row.reasonControl && (this.answers.has(`${row.questionId}::reason`) || (isFocused && this.onReasonStep))) {
        lines.push(`    ${t("dim", "reason:")}`);
        for (const line of row.reasonControl.render(Math.max(10, width - 4))) lines.push(`    ${line}`);
      }
    });
