import { initTheme } from "@earendil-works/pi-coding-agent";
import { theme as piTheme } from "@earendil-works/pi-coding-agent/dist/modes/interactive/theme/theme.js";
import {
  renderCard,
  renderQuizCard,
  renderGoalCard,
  renderGoalListCard,
  renderArtifactPreview,
  AnswerFormComponent,
} from "/home/diogenes/Projects/keating/src/pi/tui-components.ts";
import { generateQuiz } from "/home/diogenes/Projects/keating/src/core/quiz.ts";
import { buildGoal, advanceGoalStep } from "/home/diogenes/Projects/keating/src/core/goals.ts";
import { writeFileSync } from "node:fs";

// Build a real theme instance the way pi does internally.
initTheme();
const theme = piTheme;

console.log("=== renderCard ===");
console.log(renderCard(theme, "Test Card", ["line one", "a longer line that should wrap nicely across the box width"]).render(60).join("\n"));

console.log("\n=== Quiz generation + renderQuizCard ===");
const quiz = generateQuiz("derivatives");
console.log(`quiz has ${quiz.questions.length} questions, types: ${[...new Set(quiz.questions.map((q) => q.type))].join(", ")}`);
const answers = new Map(quiz.questions.map((q) => [q.id, quiz.answerKey.get(q.id) ?? ""]));
console.log(renderQuizCard(theme, quiz, { answers }).render(70).join("\n"));

console.log("\n=== Goal build + renderGoalCard ===");
const goal = buildGoal({ title: "Ship a personal website", topic: "derivatives" });
console.log(`goal has ${goal.steps.length} steps`);
console.log(renderGoalCard(theme, goal).render(70).join("\n"));

console.log("\n=== advanceGoalStep + renderGoalListCard ===");
const advanced = advanceGoalStep(goal, goal.steps[0].id, "done");
console.log(renderGoalListCard(theme, [advanced]).render(70).join("\n"));

console.log("\n=== renderArtifactPreview (missing file, should not throw) ===");
console.log(renderArtifactPreview(theme, "Missing", "/tmp/does-not-exist.md").render(60).join("\n"));

console.log("\n=== AnswerFormComponent: choice question ===");
{
  let resolved: Record<string, string> | undefined;
  const form = new AnswerFormComponent(theme, [
    { id: "q1", prompt: "Pick one", kind: "choice", choices: ["Alpha", "Beta", "Gamma"] },
  ], (r) => { resolved = r; });
  form.invalidate = () => {};
  console.log(form.render(60).join("\n"));
  // Move selection down once, then confirm.
  form.handleInput("\x1b[B"); // down arrow
  form.handleInput("\r"); // enter
  console.log("resolved:", JSON.stringify(resolved));
  if (!resolved || resolved.q1 !== "Beta") throw new Error(`expected Beta, got ${JSON.stringify(resolved)}`);
}

console.log("\n=== AnswerFormComponent: text question ===");
{
  let resolved: Record<string, string> | undefined;
  const form = new AnswerFormComponent(theme, [
    { id: "q1", prompt: "Type something", kind: "text" },
  ], (r) => { resolved = r; });
  form.invalidate = () => {};
  for (const ch of "hello world") form.handleInput(ch);
  form.handleInput("\r");
  console.log("resolved:", JSON.stringify(resolved));
  if (!resolved || resolved.q1 !== "hello world") throw new Error(`expected 'hello world', got ${JSON.stringify(resolved)}`);
}

console.log("\n=== AnswerFormComponent: choice with allow_text (Other) ===");
{
  let resolved: Record<string, string> | undefined;
  const form = new AnswerFormComponent(theme, [
    { id: "q1", prompt: "Pick or type", kind: "choice", choices: ["Red", "Blue"], allowText: true },
  ], (r) => { resolved = r; });
  form.invalidate = () => {};
  // Move down twice to reach "Other" (index 2), confirm to enter follow-up, type, confirm again.
  form.handleInput("\x1b[B");
  form.handleInput("\x1b[B");
  form.handleInput("\r");
  console.log("mid-render (should show follow-up input):\n" + form.render(60).join("\n"));
  for (const ch of "Green") form.handleInput(ch);
  form.handleInput("\r");
  console.log("resolved:", JSON.stringify(resolved));
  if (!resolved || resolved.q1 !== "Green") throw new Error(`expected Green, got ${JSON.stringify(resolved)}`);
}

console.log("\n=== AnswerFormComponent: classification with reasons ===");
{
  let resolved: Record<string, string> | undefined;
  const form = new AnswerFormComponent(theme, [
    {
      id: "q1",
      prompt: "Classify",
      kind: "classification",
      items: ["cat", "dog"],
      choices: ["mammal", "reptile"],
      requireReasons: true,
    },
  ], (r) => { resolved = r; });
  form.invalidate = () => {};
  // Row 0 (cat): confirm select "mammal" (index 0 default), then type reason, confirm.
  form.handleInput("\r");
  for (const ch of "has fur") form.handleInput(ch);
  form.handleInput("\r");
  // Row 1 (dog): confirm select "mammal", type reason, confirm -> done.
  form.handleInput("\r");
  for (const ch of "also has fur") form.handleInput(ch);
  form.handleInput("\r");
  console.log("resolved:", JSON.stringify(resolved));
  if (resolved?.["q1::0"] !== "mammal" || resolved?.["q1::0::reason"] !== "has fur") {
    throw new Error(`unexpected classification result: ${JSON.stringify(resolved)}`);
  }
}

console.log("\nALL CHECKS PASSED");

