{
  let resolved: Record<string, string> | undefined;
  const form = new AnswerFormComponent(theme, [
    {
      id: "q1",
      prompt: "Classify",
      kind: "classification",
      items: ["cat", "dog"],
      choices: ["mammal", "reptile"],
      requireReasons: true,
    },
  ], (r) => { resolved = r; });
  form.invalidate = () => {};
  // Row 0 (cat): confirm select "mammal" (index 0 default), then type reason, confirm.
  form.handleInput("\r");
  for (const ch of "has fur") form.handleInput(ch);
  form.handleInput("\r");
  // Row 1 (dog): confirm select "mammal", type reason, confirm -> done.
  form.handleInput("\r");
  for (const ch of "also has fur") form.handleInput(ch);
  form.handleInput("\r");
  console.log("resolved:", JSON.stringify(resolved));
  if (resolved?.["q1::0"] !== "mammal" || resolved?.["q1::0::reason"] !== "has fur") {
    throw new Error(`unexpected classification result: ${JSON.stringify(resolved)}`);
  }
}

