52	const ANSI_RE = /\x1b\[[0-9;]*[a-zA-Z]/g;
53	
54	function visibleWidth(text: string): number {
55	 return text.replace(ANSI_RE, "").length;
56	}
57	
58	function truncateVisible(text: string, width: number): string {
59	 const limit = Math.max(0, width);
60	 if (visibleWidth(text) <= limit) return text;
61	 if (limit === 0) return "";
62	
63	 const suffix = limit > 1 ? "…" : "";
64	 const contentLimit = Math.max(0, limit - visibleWidth(suffix));
65	 let visible = 0;
66	 let output = "";
67	
68	 for (let index = 0; index < text.length;) {
69	 const ansi = text.slice(index).match(/^\x1b\[[0-9;]*[a-zA-Z]/);
70	 if (ansi) {
71	 output += ansi[0];
72	 index += ansi[0].length;
73	 continue;
74	 }
75	
76	 if (visible >= contentLimit) break;
77	 output += text[index];
78	 visible += 1;
79	 index += 1;
80	 }
81	
82	 return `${output}${suffix}`;
83	}
84	
85	function padVisible(text: string, width: number): string {
86	 const fitted = truncateVisible(text, width);
87	 const vw = visibleWidth(fitted);
88	 return vw >= width ? fitted : fitted + " ".repeat(width - vw);
89	}
90	
91	function truncatePlain(text: string, width: number): string {
92	 if (text.length <= width) return text;
93	 if (width <= 1) return text.slice(0, Math.max(0, width));
94	 return `${text.slice(0, width - 1)}…`;
95	}
96	
97	function centerPlain(text: string, width: number): string {
98	 const truncated = truncatePlain(text, width);
99	 const gap = Math.max(0, width - truncated.length);
100	 const left = Math.floor(gap / 2);
101	 return `${" ".repeat(left)}${truncated}${" ".repeat(gap - left)}`;
102	}
103	
104	function wrapWords(text: string, maxWidth: number): string[] {
105	 const width = Math.max(1, maxWidth);
106	 const words = text.split(/\s+/).filter(Boolean);
107	 const lines: string[] = [];
108	 let current = "";
109	
110	 for (const raw of words) {
111	 const word = truncatePlain(raw, width);
112	 const next = current ? `${current} ${word}` : word;
113	 if (current && next.length > width) {
114	 lines.push(current);
115	 current = word;
116	 } else {
117	 current = next;
118	 }
119	 }
120	
121	 if (current) lines.push(current);
122	 return lines.length > 0 ? lines : [""];
123	}
124	
125	function formatHeaderPath(path: string): string {
126	 const home = homedir();
127	 return path.startsWith(home) ? `~${path.slice(home.length)}` : path;
128	}
129	
