770	 if (!topic) return { content: [{ type: "text", text: "Topic required." }] };
771	 const quiz = generateQuiz(topic);
772	
773	 if (typeof ctx?.ui?.custom === "function" && ctx.hasUI) {
774	 const formQuestions: AnswerFormQuestion[] = quiz.questions.map((q) => ({
775	 id: q.id,
776	 prompt: q.question,
