788	 if (isObjective) {
789	 const expected = (quiz.answerKey.get(q.id) ?? "").trim().toLowerCase();
790	 const given = (rawAnswers[q.id] ?? "").trim().toLowerCase();
791	 objectiveResults[q.id] = given.length > 0 && given === expected;
792	 } else {
793	 openEndedIds.push(q.id);
794	 }
795	 }
