 // ── Feedback ──
 keatingToolMaker(
 "feedback",
 "feedback",
 "Record a learner feedback signal for a topic. Call this after teaching to track session outcomes. signal must be 'up', 'down', or 'confused'.",
 {
 signal: { type: "string", enum: ["up", "down", "confused"], description: "Feedback signal: up, down, or confused" },
 topic: { type: "string", description: "The topic the feedback is about (defaults to 'general')" }
 },
 async (params) => {
 const signalMap: Record<string, typeof up | typeof down | typeof confused> = { up, down, confused };
 const s = signalMap[pick(params.signal as string)];
 if (!s) return { content: [{ type: "text", text: "signal must be 'up', 'down', or 'confused'." }] };
 const topic = (params.topic as string) || "general";
 const statePath = learnerStatePath(getCwd());
 const state = await loadLearnerState(statePath);
 recordFeedback(state, topic, s);
 await saveLearnerState(statePath, state);
 return {
 content: [{ type: "text", text: `Recorded ${s} feedback for "${topic}".` }],
 details: { signal: s, topic }
 };
 }
 ),

 // ── Goals ──
 keatingToolMaker(
 "set_learner_goal",
 "set_learner_goal",
 "Create or update a long-horizon learner goal with a curriculum of steps. Use when the learner wants to accomplish something over multiple sessions (a project, a skill, a milestone). If steps are omitted, a default research→practice→build→teach curriculum is scaffolded from 'topic'.",
 {
 title: { type: "string", description: "The goal title, e.g. 'Ship a personal website'." },
 description: { type: "string", description: "Optional longer description of the goal." },
 motivation: { type: "string", description: "Optional: why this goal matters to the learner." },
 target_date: { type: "string", description: "Optional target completion date." },
 topic: { type: "string", description: "Optional anchor topic used to auto-scaffold a curriculum when steps are omitted." },
 steps: {
 type: "array",
 description: "Optional agent-authored curriculum steps, in order.",
 items: {
 type: "object",
 properties: {
 title: { type: "string" },
 description: { type: "string" },
 kind: { type: "string", enum: ["concept", "practice", "project", "milestone", "reflection"] },
 topic: { type: "string" },
 success_criteria: { type: "array", items: { type: "string" } }
 },
 required: ["title"]
 }
 }
 },
 async (params) => {
 const title = (params.title as string) || "";
 if (!title) return { content: [{ type: "text", text: "Goal title is required." }] };
 const stepsInput = Array.isArray(params.steps) ? (params.steps as Record<string, unknown>[]) : undefined;
 const steps: GoalStepInput[] | undefined = stepsInput
 ?.filter((s) => typeof s.title === "string" && s.title.trim().length > 0)
 .map((s) => ({
 title: s.title as string,
 description: typeof s.description === "string" ? s.description : undefined,
 kind: s.kind as GoalStepInput["kind"],
 topic: typeof s.topic === "string" ? s.topic : undefined,
 successCriteria: Array.isArray(s.success_criteria) ? (s.success_criteria as string[]) : undefined
 }));
 const goal = buildGoal({
 title,
 description: params.description as string | undefined,
 motivation: params.motivation as string | undefined,
 targetDate: params.target_date as string | undefined,
 topic: params.topic as string | undefined,
 steps
 });
 await ensureProjectScaffold(getCwd());
 await upsertGoal(goalsStatePath(getCwd()), goal);
 return {
 content: [{ type: "text", text: `Created goal "${goal.title}" (id: ${goal.id}) with ${goal.steps.length} steps.` }],
 details: { goal }
 };
 },
 { result: (result: any, _options: any, theme: any) => (result?.details?.goal ? renderGoalCard(theme, result.details.goal) : undefined) }
 ),
 keatingToolMaker(
 "list_learner_goals",
 "list_learner_goals",
 "List the learner's saved goals and their progress. Optionally filter by status.",
 { status: { type: "string", enum: ["active", "completed", "paused"], description: "Optional status filter." } },
 async (params) => {
 const goals = await loadGoals(goalsStatePath(getCwd()));
 const filtered = typeof params.status === "string" ? goals.filter((g) => g.status === params.status) : goals;
 const summary =
 filtered.length === 0
 ? "No goals found."
 : filtered.map((g) => `- ${g.id}: ${g.title} (${g.status}, ${g.steps.filter((s) => s.status === "done").length}/${g.steps.length} steps)`).join("\n");
 return {
 content: [{ type: "text", text: summary }],
 details: { goals: filtered }
 };
 },
 { result: (result: any, _options: any, theme: any) => (Array.isArray(result?.details?.goals) ? renderGoalListCard(theme, result.details.goals) : undefined) }
 ),
 keatingToolMaker(
 "update_goal_step",
 "update_goal_step",
 "Update the status of one step within a learner goal (e.g. mark it in progress or done). Use goal_id and step_id from set_learner_goal or list_learner_goals.",
 {
 goal_id: { type: "string", description: "The goal id." },
 step_id: { type: "string", description: "The step id to update." },
 status: { type: "string", enum: ["not_started", "in_progress", "done"], description: "The new status for the step." }
 },
 async (params) => {
 const goalId = (params.goal_id as string) || "";
 const stepId = (params.step_id as string) || "";
 const status = params.status as string;
 if (!goalId || !stepId || (status !== "not_started" && status !== "in_progress" && status !== "done")) {
 return { content: [{ type: "text", text: "goal_id, step_id, and a valid status ('not_started'|'in_progress'|'done') are required." }] };
 }
 const path = goalsStatePath(getCwd());
 const goals = await loadGoals(path);
 const goal = goals.find((g) => g.id === goalId);
 if (!goal) return { content: [{ type: "text", text: `No goal found with id "${goalId}".` }] };
 const updated = advanceGoalStep(goal, stepId, status);
 await upsertGoal(path, updated);
 return {
 content: [{ type: "text", text: `Updated step to "${status}" in goal "${updated.title}".` }],
 details: { goal: updated }
 };
 },
 { result: (result: any, _options: any, theme: any) => (result?.details?.goal ? renderGoalCard(theme, result.details.goal) : undefined) }
 ),

 keatingToolMaker(
 "ask_user_question",
 "ask_user_question",
 "Ask the learner a direct question with optional multiple-choice, text, fill-in-the-blank, classification-table, or matching-worksheet answers. Use to check understanding, prompt reflection, or gather the learner's thinking before explaining a concept. The agent waits for the user's answer in the next message.",
 {
 question: { type: "string", description: "The question to ask the learner" },
 choices: { type: "array", items: { type: "string" }, description: "Optional list of answer choices. For classification questions, these are categories/slots; for matching questions, answer-bank entries." },
 items: { type: "array", items: { type: "string" }, description: "Rows to classify or prompts to match when type is 'classification' or 'matching'." },
 type: { type: "string", enum: ["choice", "text", "blanks", "classification", "matching"], description: "Question type. Use 'classification' to assign each item to a category; use 'matching' for worksheet-style prompt-to-answer matching." },
 allow_text: { type: "boolean", description: "Whether to also allow free-text input (default: true if no choices, false if choices provided)" },
 require_reasons: { type: "boolean", description: "For classification questions, require a short justification per row (default true)." },
 unique_matches: { type: "boolean", description: "For matching questions, prevent reusing an answer-bank choice (default true)." },
 correct_matches: { type: "array", items: { type: "string" }, description: "Optional answer key for matching questions, one correct choice per item in order. Enables red/green feedback after submission." },
 item_label: { type: "string", description: "Column label for classification items." },
 choice_label: { type: "string", description: "Column label for classification choices or matching answer bank." },
 reason_label: { type: "string", description: "Column label for classification justifications." },
 hint: { type: "string", description: "Optional hint to display below the question" },
 },
 async (params, ctx) => {
 const question = (params.question as string) || "";
 if (!question) return { content: [{ type: "text", text: "Question text is required." }] };
 const choices = Array.isArray(params.choices) ? params.choices.filter((c: unknown) => typeof c === "string") as string[] : undefined;
 const items = Array.isArray(params.items) ? params.items.filter((item: unknown) => typeof item === "string") as string[] : undefined;
 const type = typeof params.type === "string" ? params.type : undefined;
 if ((type === "classification" || type === "matching") && (!items || items.length === 0 || !choices || choices.length === 0)) {
 return { content: [{ type: "text", text: "Classification and matching questions require both items and choices." }] };
 }
 const allowText = type === "classification" || type === "matching" ? false : typeof params.allow_text === "boolean" ? params.allow_text : !choices || choices.length === 0;
 const hint = (params.hint as string) || undefined;
 const resolvedKind = (type ?? (choices && choices.length > 0 ? "choice" : "text")) as AnswerFormQuestion["kind"];

 if (typeof ctx?.ui?.custom === "function" && ctx.hasUI) {
 const formQuestion: AnswerFormQuestion = {
 id: "q1",
 prompt: hint ? `${question}\n(hint: ${hint})` : question,
 kind: resolvedKind,
 choices,
 items,
 allowText,
 requireReasons: typeof params.require_reasons === "boolean" ? params.require_reasons : true,
 };
 const rawAnswers: Record<string, string> = await ctx.ui.custom((_tui: any, theme: any, _keybindings: any, done: (result: Record<string, string>) => void) => {
 return new AnswerFormComponent(theme, [formQuestion], done);
 });
 const summary =
 resolvedKind === "classification" || resolvedKind === "matching"
 ? (items ?? [])
 .map((item, idx) => {
 const choice = rawAnswers[`q1::${idx}`] ?? "(no answer)";
 const reason = rawAnswers[`q1::${idx}::reason`];
 return `${item} → ${choice}${reason ? ` (${reason})` : ""}`;
 })
 .join("; ")
 : (rawAnswers.q1 ?? "(no answer)");
 return {
 content: [{ type: "text", text: `Learner answered: ${summary}` }],
 details: { question, choices, items, type: resolvedKind, answers: rawAnswers }
 };
 }

 // Non-interactive fallback (rpc/print/json modes, or hosts without ctx.ui.custom): print
 // a machine-readable tag and let the conversation continue with the learner's next message.
 const correctMatches = Array.isArray(params.correct_matches) ? params.correct_matches.filter((item: unknown) => typeof item === "string") as string[] : undefined;
 const payload = JSON.stringify({
 question,
 type,
 choices,
 items,
 allow_text: allowText,
 require_reasons: typeof params.require_reasons === "boolean" ? params.require_reasons : undefined,
 unique_matches: typeof params.unique_matches === "boolean" ? params.unique_matches : undefined,
 correct_matches: correctMatches && correctMatches.length > 0 ? correctMatches : undefined,
 item_label: typeof params.item_label === "string" ? params.item_label : undefined,
 choice_label: typeof params.choice_label === "string" ? params.choice_label : undefined,
 reason_label: typeof params.reason_label === "string" ? params.reason_label : undefined,
 hint
 });
 return {
 content: [{ type: "text", text: `[question] Asking learner: ${question}${choices ? ` (choices: ${choices.join(", ")})` : ""}\n<keating-question json=${JSON.stringify(payload)} />` }],
 details: { question, choices, allow_text: allowText, hint }
 };
 }
 ),
 ];

 for (const tool of tools) {
 pi.registerTool(tool as any);
 }

 if (typeof pi === "object" && pi !== null) {
 keatingToolRegistrations.add(pi);
 }
}

