1	import { readFileSync } from "node:fs";
2	import {
3	  Input,
4	  SelectList,
5	  type Component,
6	  type SelectItem,
7	  truncateToWidth,
8	  wrapTextWithAnsi,
9	} from "@earendil-works/pi-tui";
10	import { getSelectListTheme } from "@earendil-works/pi-coding-agent";
11	import type { Quiz, QuizQuestion } from "../core/quiz.js";
12	import type { LearnerGoal } from "../core/goals.js";
13	
14	// pi's Theme type isn't re-exported at a stable path we can safely import from an
15	// extension package; every other Component builder in hyperteacher-extension.ts
16	// treats it as `any` too (see createKeatingHeaderComponent), so we match that.
17	type Theme = any;
18	
19	function pad(text: string, width: number): string {
20	  return truncateToWidth(text, Math.max(0, width), "…", true);
21	}
22	
23	function wrap(text: string, width: number): string[] {
24	  return wrapTextWithAnsi(text, Math.max(1, width));
25	}
26	
27	/** A static (non-interactive) bordered card, matching the visual style of createKeatingHeaderComponent. */
28	export function renderCard(theme: Theme, heading: string, bodyLines: string[]): Component {
29	  const t = theme.fg.bind(theme);
30	  const b = theme.bold.bind(theme);
31	  const border = (text: string) => t("borderMuted", text);
32	  const headingText = b(t("mdHeading", heading));
33	
34	  return {
35	    render(width: number): string[] {
36	      const cardWidth = Math.min(Math.max(width - 2, 20), 100);
37	      const innerWidth = cardWidth - 4;
38	      const lines: string[] = [];
39	      lines.push(border(`╭${"─".repeat(cardWidth - 2)}╮`));
40	      lines.push(`${border("│")} ${pad(headingText, innerWidth)} ${border("│")}`);
41	      lines.push(`${border("├")}${border("─".repeat(cardWidth - 2))}${border("┤")}`);
42	      for (const raw of bodyLines) {
43	        const wrapped = raw.length === 0 ? [""] : wrap(raw, innerWidth);
44	        for (const line of wrapped) {
45	          lines.push(`${border("│")} ${pad(line, innerWidth)} ${border("│")}`);
46	        }
47	      }
48	      lines.push(border(`╰${"─".repeat(cardWidth - 2)}╯`));
49	      return lines;
50	    },
51	    invalidate() {},
52	  };
53	}
54	
55	/** Reads a just-written artifact file from disk and renders it as a bordered markdown preview. */
56	export function renderArtifactPreview(theme: Theme, title: string, filePath: string, maxLines = 40): Component {
57	  let bodyLines: string[];
58	  try {
59	    const raw = readFileSync(filePath, "utf8");
60	    const allLines = raw.split("\n");
61	    bodyLines = allLines.slice(0, maxLines);
62	    if (allLines.length > maxLines) {
63	      bodyLines.push("", `… ${allLines.length - maxLines} more lines (see ${filePath})`);
64	    }
65	  } catch {
66	    bodyLines = [`(could not read ${filePath})`];
67	  }
68	  return renderCard(theme, title, bodyLines);
69	}
70	
71	const QUESTION_STATUS_GLYPH: Record<"unanswered" | "answered" | "correct" | "incorrect" | "pending_grade", string> = {
72	  unanswered: "○",
73	  answered: "●",
74	  correct: "✓",
75	  incorrect: "✗",
76	  pending_grade: "…",
77	};
78	
79	export interface QuizCardState {
80	  answers?: Map<string, string>;
81	  objectiveResults?: Map<string, boolean>;
82	  openEndedGrades?: Map<string, { verdict: "correct" | "incorrect" | "partial"; note?: string }>;
83	}
84	
85	function questionStatus(q: QuizQuestion, state: QuizCardState): keyof typeof QUESTION_STATUS_GLYPH {
86	  const graded = state.openEndedGrades?.get(q.id);
87	  if (graded) return graded.verdict === "partial" ? "answered" : graded.verdict;
88	  const objective = state.objectiveResults?.get(q.id);
89	  if (objective !== undefined) return objective ? "correct" : "incorrect";
90	  const isOpenEnded = q.type === "short_answer" || q.type === "transfer";
91	  if (isOpenEnded && state.answers?.has(q.id)) return "pending_grade";
92	  return state.answers?.has(q.id) ? "answered" : "unanswered";
93	}
94	
95	export function renderQuizCard(theme: Theme, quiz: Quiz, state: QuizCardState = {}): Component {
96	  const lines: string[] = [];
97	  let correct = 0;
98	  let graded = 0;
99	  for (const q of quiz.questions) {
100	    const status = questionStatus(q, state);
101	    if (status === "correct") correct++;
102	    if (status === "correct" || status === "incorrect") graded++;
103	    lines.push(`${QUESTION_STATUS_GLYPH[status]} [${q.level}] ${q.question}`);
104	    const answer = state.answers?.get(q.id);
105	    if (answer) lines.push(`   your answer: ${answer}`);
106	    const note = state.openEndedGrades?.get(q.id)?.note;
107	    if (note) lines.push(`   feedback: ${note}`);
108	  }
109	  if (graded > 0) {
110	    lines.unshift("", `Objective score: ${correct}/${graded}`);
111	  }
112	  return renderCard(theme, `Quiz: ${quiz.topic}`, lines);
113	}
114	
115	function progressBar(percent: number, width = 20): string {
116	  const filled = Math.round((Math.max(0, Math.min(100, percent)) / 100) * width);
117	  return `[${"#".repeat(filled)}${"-".repeat(width - filled)}] ${percent}%`;
118	}
119	
120	const GOAL_STEP_GLYPH: Record<string, string> = {
121	  not_started: "[ ]",
122	  in_progress: "[~]",
123	  done: "[x]",
124	};
125	
126	export function renderGoalCard(theme: Theme, goal: LearnerGoal): Component {
127	  const total = goal.steps.length;
128	  const done = goal.steps.filter((s) => s.status === "done").length;
129	  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
130	  const nextStep = goal.steps.find((s) => s.status !== "done");
131	
132	  const lines: string[] = [];
133	  if (goal.description) lines.push(goal.description, "");
134	  lines.push(`Progress: ${progressBar(percent)} (${done}/${total})`, `Status: ${goal.status}`);
135	  if (nextStep) lines.push(`Next: ${nextStep.title}`);
136	  lines.push("");
137	  for (const step of goal.steps) {
138	    lines.push(`${GOAL_STEP_GLYPH[step.status] ?? "[ ]"} ${step.order + 1}. ${step.title} (${step.kind})`);
139	  }
140	  return renderCard(theme, `Goal: ${goal.title}`, lines);
141	}
142	
143	export function renderGoalListCard(theme: Theme, goals: LearnerGoal[]): Component {
144	  if (goals.length === 0) return renderCard(theme, "Learner Goals", ["No goals yet."]);
145	  const lines = goals.map((g) => {
146	    const total = g.steps.length;
147	    const done = g.steps.filter((s) => s.status === "done").length;
148	    return `${g.status === "completed" ? "✓" : "•"} [${g.id}] ${g.title} — ${done}/${total} steps (${g.status})`;
149	  });
150	  return renderCard(theme, "Learner Goals", lines);
151	}
152	
153	// ─── Interactive answer collection ─────────────────────────────────────────
154	
155	export type AnswerFormKind = "choice" | "text" | "blanks" | "classification" | "matching";
156	
157	export interface AnswerFormQuestion {
158	  id: string;
159	  prompt: string;
160	  kind: AnswerFormKind;
161	  choices?: string[];
162	  items?: string[];
163	  allowText?: boolean;
164	  requireReasons?: boolean;
165	  uniqueMatches?: boolean;
166	}
167	
168	export interface AnswerFormResult {
169	  [questionId: string]: string;
170	}
171	
172	const OTHER_ITEM_VALUE = "__answer_form_other__";
173	
174	/**
175	 * A blocking, keyboard-driven form. Renders one or more questions vertically;
176	 * only the focused row receives keystrokes. Supports choice (SelectList),
177	 * free text (Input), and per-row choice sequences for classification/matching
178	 * (one SelectList + optional reason Input per item/row).
179	 */
180	interface FormRow {
181	  questionId: string;
182	  label: string;
183	  control: SelectList | Input;
